-- PHY 102 (old PHY 124): second set of 46 questions - sources of magnetic field, inductance,
-- Maxwell's equations, more electrostatics, DC circuits and atomic/nuclear physics.
-- All answers re-solved and checked numerically. Original wording; ADDS ONLY, repeats skipped.
with src (question, options, correct_index, explanation, topic) as (
values
  ('A circular loop of radius $10\ \text{cm}$ carries $5.0\ \text{A}$. The magnetic field at its centre is:', '["$1.57\\times10^{-5}\\ \\text{T}$","$6.28\\times10^{-5}\\ \\text{T}$","$3.14\\times10^{-5}\\ \\text{T}$","$9.87\\times10^{-5}\\ \\text{T}$"]'::jsonb, 2, 'At the centre of a loop, $B = \mu_{0}I/(2R) = (4\pi\times10^{-7})(5)/(0.2) = 3.1\times10^{-5}\ \text{T}$.', 'Magnetic Fields and Forces'),
  ('A flat coil of $20$ turns and radius $5.0\ \text{cm}$ carries $2.0\ \text{A}$. The field at its centre is:', '["$2.51\\times10^{-5}\\ \\text{T}$","$1.01\\times10^{-3}\\ \\text{T}$","$2.51\\times10^{-4}\\ \\text{T}$","$5.03\\times10^{-4}\\ \\text{T}$"]'::jsonb, 3, '$B = \mu_{0}NI/(2R) = (4\pi\times10^{-7})(20)(2)/(0.1) = 5.0\times10^{-4}\ \text{T}$.', 'Magnetic Fields and Forces'),
  ('A loop of radius $4.0\ \text{cm}$ carries $3.0\ \text{A}$. What is the field on its axis at $3.0\ \text{cm}$ from the centre?', '["$2.41\\times10^{-5}\\ \\text{T}$","$4.83\\times10^{-5}\\ \\text{T}$","$1.21\\times10^{-5}\\ \\text{T}$","$4.71\\times10^{-5}\\ \\text{T}$"]'::jsonb, 0, '$B = \dfrac{\mu_{0}IR^{2}}{2(R^{2} + z^{2})^{3/2}} = \dfrac{(4\pi\times10^{-7})(3)(0.04)^{2}}{2(0.0025)^{3/2}} \approx 2.4\times10^{-5}\ \text{T}$.', 'Magnetic Fields and Forces'),
  ('A circular arc of radius $20\ \text{cm}$ subtends $90^{\circ}$ at its centre and carries $10\ \text{A}$. The field at the centre is:', '["$1.57\\times10^{-5}\\ \\text{T}$","$7.85\\times10^{-6}\\ \\text{T}$","$3.14\\times10^{-5}\\ \\text{T}$","$3.93\\times10^{-6}\\ \\text{T}$"]'::jsonb, 1, 'A $90^{\circ}$ arc is one quarter of a loop: $B = \tfrac{1}{4}\mu_{0}I/(2R) = (4\pi\times10^{-7})(10)/(8\times0.2) = 7.85\times10^{-6}\ \text{T}$.', 'Magnetic Fields and Forces'),
  ('Two long parallel wires $5.0\ \text{cm}$ apart carry $10\ \text{A}$ and $20\ \text{A}$ in the same direction. The force per metre between them is:', '["$8\\times10^{-4}\\ \\text{N/m}$, repulsive","$1.6\\times10^{-3}\\ \\text{N/m}$, attractive","$8\\times10^{-4}\\ \\text{N/m}$, attractive","$4\\times10^{-4}\\ \\text{N/m}$, repulsive"]'::jsonb, 2, '$F/L = \mu_{0}I_{1}I_{2}/(2\pi d) = (2\times10^{-7})(10)(20)/0.05 = 8\times10^{-4}\ \text{N/m}$. Parallel currents attract.', 'Magnetic Fields and Forces'),
  ('Ampere''s law states that $\oint \mathbf{B}\cdot d\mathbf{l}$ around a closed path equals:', '["$I_{\\text{enc}}/\\mu_{0}$","$\\mu_{0}$ times the total current of the whole circuit","zero for every closed path","$\\mu_{0}I_{\\text{enc}}$"]'::jsonb, 3, 'Only the current enclosed by the path counts: $\oint \mathbf{B}\cdot d\mathbf{l} = \mu_{0}I_{\text{enc}}$.', 'Magnetic Fields and Forces'),
  ('A toroid has $500$ turns and carries $2.0\ \text{A}$. The field at a radius of $15\ \text{cm}$ inside the toroid is:', '["$1.33\\times10^{-3}\\ \\text{T}$","$6.67\\times10^{-4}\\ \\text{T}$","$2.67\\times10^{-3}\\ \\text{T}$","$1.33\\times10^{-2}\\ \\text{T}$"]'::jsonb, 0, '$B = \mu_{0}NI/(2\pi r) = (4\pi\times10^{-7})(500)(2)/(2\pi\times0.15) = 1.33\times10^{-3}\ \text{T}$.', 'Magnetic Fields and Forces'),
  ('Outside an ideal long solenoid, the magnetic field is:', '["equal to the field inside","approximately zero","twice the field inside","infinite near the windings"]'::jsonb, 1, 'For an ideal solenoid, Ampere''s law applied to a loop outside gives $B \approx 0$.', 'Magnetic Fields and Forces'),
  ('A long straight wire of radius $2.0\ \text{cm}$ carries a uniform current of $5.0\ \text{A}$. The field inside it at $1.0\ \text{cm}$ from the axis is:', '["$5\\times10^{-5}\\ \\text{T}$","$1.25\\times10^{-5}\\ \\text{T}$","$2.5\\times10^{-5}\\ \\text{T}$","$1\\times10^{-4}\\ \\text{T}$"]'::jsonb, 2, 'Inside, $I_{\text{enc}} = I(r/R)^{2}$. So $B = \mu_{0}Ir/(2\pi R^{2}) = (2\times10^{-7})(5)(0.01)/(0.02)^{2} = 2.5\times10^{-5}\ \text{T}$.', 'Magnetic Fields and Forces'),
  ('According to the Biot-Savart law, the field element $d\mathbf{B}$ due to a current element $I\,d\mathbf{l}$ at displacement $\mathbf{r}$ is proportional to:', '["$I\\,d\\mathbf{l}\\cdot\\hat{\\mathbf{r}}/r$","$I\\,d\\mathbf{l}\\times\\hat{\\mathbf{r}}/r^{3}\\ \\text{only for straight wires}$","$I\\,r^{2}\\,d\\mathbf{l}$","$I\\,d\\mathbf{l}\\times\\hat{\\mathbf{r}}/r^{2}$"]'::jsonb, 3, '$d\mathbf{B} = \dfrac{\mu_{0}}{4\pi}\dfrac{I\,d\mathbf{l}\times\hat{\mathbf{r}}}{r^{2}}$: perpendicular to both the element and $\hat{\mathbf{r}}$, falling off as $1/r^{2}$.', 'Magnetic Fields and Forces'),
  ('A solenoid has $1000$ turns, length $50\ \text{cm}$ and cross-sectional area $4.0\ \text{cm}^{2}$. Its self-inductance is about:', '["$1.01\\times10^{-3}\\ \\text{H}$","$1.01\\times10^{-2}\\ \\text{H}$","$1.01\\times10^{-4}\\ \\text{H}$","$2.01\\times10^{-3}\\ \\text{H}$"]'::jsonb, 0, '$L = \mu_{0}N^{2}A/l = (4\pi\times10^{-7})(10^{6})(4\times10^{-4})/0.5 = 1.0\times10^{-3}\ \text{H}$.', 'Electromagnetic Induction'),
  ('How much energy is stored in a $0.20\ \text{H}$ inductor carrying $3.0\ \text{A}$?', '["$1.8\\ \\text{J}$","$0.90\\ \\text{J}$","$0.60\\ \\text{J}$","$0.45\\ \\text{J}$"]'::jsonb, 1, '$U = \tfrac{1}{2}LI^{2} = \tfrac{1}{2}(0.2)(9) = 0.90\ \text{J}$.', 'Electromagnetic Induction'),
  ('The current in a $0.50\ \text{H}$ inductor changes uniformly from $0$ to $4.0\ \text{A}$ in $10\ \text{ms}$. The magnitude of the induced e.m.f. is:', '["$20\\ \\text{V}$","$2.0\\ \\text{V}$","$200\\ \\text{V}$","$0.2\\ \\text{V}$"]'::jsonb, 2, '$|\varepsilon| = L\,|\Delta I/\Delta t| = 0.5\times4/0.01 = 200\ \text{V}$.', 'Electromagnetic Induction'),
  ('A $0.50\ \text{H}$ inductor is in series with a $25\ \Omega$ resistor. The time constant of the circuit is:', '["$50\\ \\text{s}$","$12.5\\ \\text{s}$","$0.20\\ \\text{s}$","$0.020\\ \\text{s}$"]'::jsonb, 3, '$\tau = L/R = 0.5/25 = 0.020\ \text{s}$.', 'Electromagnetic Induction'),
  ('A $12\ \text{V}$ battery is switched onto a series LR circuit with $R = 6\ \Omega$ and $\tau = L/R$. After one time constant the current is about:', '["$1.26\\ \\text{A}$","$2.00\\ \\text{A}$","$0.74\\ \\text{A}$","$1.00\\ \\text{A}$"]'::jsonb, 0, '$I = (V/R)(1 - e^{-t/\tau})$. At $t = \tau$: $I = 2(1 - 0.368) = 1.26\ \text{A}$, which is $63\%$ of the final value.', 'Electromagnetic Induction'),
  ('A coil of $200$ turns has the flux through it change uniformly from $0.50\ \text{mWb}$ to $0.10\ \text{mWb}$ in $20\ \text{ms}$. The magnitude of the induced e.m.f. is:', '["$0.4\\ \\text{V}$","$4.0\\ \\text{V}$","$20\\ \\text{V}$","$0.02\\ \\text{V}$"]'::jsonb, 1, '$|\varepsilon| = N|\Delta\Phi|/\Delta t = 200(0.4\times10^{-3})/0.02 = 4.0\ \text{V}$.', 'Electromagnetic Induction'),
  ('A rod of length $0.50\ \text{m}$ moves at $2.0\ \text{m/s}$ perpendicular to a field of $0.40\ \text{T}$, and the circuit has resistance $0.20\ \Omega$. The current and the force needed to keep it moving at constant speed are:', '["$2.0\\ \\text{A};\\ 0.80\\ \\text{N}$","$0.40\\ \\text{A};\\ 0.20\\ \\text{N}$","$2.0\\ \\text{A};\\ 0.40\\ \\text{N}$","$4.0\\ \\text{A};\\ 0.40\\ \\text{N}$"]'::jsonb, 2, '$\varepsilon = Blv = (0.4)(0.5)(2) = 0.4\ \text{V}$, so $I = 0.4/0.2 = 2.0\ \text{A}$. The magnetic force is $F = BIl = (0.4)(2)(0.5) = 0.40\ \text{N}$. Check: power $Fv = 0.8\ \text{W} = I^{2}R$.', 'Electromagnetic Induction'),
  ('Lenz''s law is a statement of the conservation of:', '["charge","linear momentum","mass","energy"]'::jsonb, 3, 'If the induced current aided the change in flux, energy would be created from nothing. The opposing direction makes the work done against the induced force the source of the electrical energy.', 'Electromagnetic Induction'),
  ('Displacement current in a charging capacitor is produced by:', '["a changing electric field between the plates","the movement of charges across the gap","a steady magnetic field","the resistance of the wires"]'::jsonb, 0, 'Maxwell added $I_{d} = \varepsilon_{0}\,d\Phi_{E}/dt$ to Ampere''s law, so a changing electric flux acts like a current in producing a magnetic field.', 'Electromagnetic Induction'),
  ('Maxwell''s equations predict that electromagnetic waves travel in vacuum at a speed equal to:', '["$\\sqrt{\\mu_{0}\\varepsilon_{0}}$","$1/\\sqrt{\\mu_{0}\\varepsilon_{0}}$","$\\mu_{0}/\\varepsilon_{0}$","$\\sqrt{\\varepsilon_{0}/\\mu_{0}}$"]'::jsonb, 1, 'Combining Maxwell''s equations gives a wave equation with speed $c = 1/\sqrt{\mu_{0}\varepsilon_{0}} \approx 3.0\times10^{8}\ \text{m/s}$.', 'Electromagnetic Induction'),
  ('In an electromagnetic wave travelling in vacuum, the electric and magnetic fields are:', '["parallel to each other and perpendicular to travel","both parallel to the direction of travel","perpendicular to each other and to the direction of travel","perpendicular to each other but along the direction of travel"]'::jsonb, 2, 'Electromagnetic waves are transverse, with $\mathbf{E}\perp\mathbf{B}\perp\mathbf{k}$ and $E = cB$.', 'Electromagnetic Induction'),
  ('The electric field amplitude of an electromagnetic wave in vacuum is $6.0\ \text{V/m}$. The magnetic field amplitude is:', '["$1.8\\times10^{9}\\ \\text{T}$","$2.0\\times10^{-6}\\ \\text{T}$","$6.0\\times10^{-8}\\ \\text{T}$","$2.0\\times10^{-8}\\ \\text{T}$"]'::jsonb, 3, '$B_{0} = E_{0}/c = 6/(3\times10^{8}) = 2.0\times10^{-8}\ \text{T}$.', 'Electromagnetic Induction'),
  ('A conducting sphere of radius $10\ \text{cm}$ carries a charge of $5.0\ \text{nC}$. What is the electric field at $30\ \text{cm}$ from its centre?', '["$500\\ \\text{N/C}$","$4500\\ \\text{N/C}$","$150\\ \\text{N/C}$","$0$"]'::jsonb, 0, 'Outside a spherical charge distribution the field is that of a point charge at the centre: $E = kQ/r^{2} = (8.99\times10^{9})(5\times10^{-9})/(0.3)^{2} = 500\ \text{N/C}$.', 'Electrostatics'),
  ('Inside a hollow conducting sphere carrying a charge, the electric field is:', '["$kQ/R^{2}$","zero","directed radially inwards","uniform and non-zero"]'::jsonb, 1, 'By Gauss''s law no net charge is enclosed inside the cavity, so $E = 0$. The charge resides on the outer surface.', 'Electrostatics'),
  ('An infinitely long line of charge has linear density $2.0\ \mu\text{C/m}$. The electric field at $0.50\ \text{m}$ is:', '["$3.6\\times10^{4}\\ \\text{N/C}$","$1.44\\times10^{5}\\ \\text{N/C}$","$7.19\\times10^{4}\\ \\text{N/C}$","$7.19\\times10^{2}\\ \\text{N/C}$"]'::jsonb, 2, '$E = \lambda/(2\pi\varepsilon_{0}r) = 2k\lambda/r = 2(8.99\times10^{9})(2\times10^{-6})/0.5 = 7.2\times10^{4}\ \text{N/C}$.', 'Electrostatics'),
  ('An infinite non-conducting sheet carries a surface charge density of $3.0\ \mu\text{C/m}^{2}$. The field near it is:', '["$3.39\\times10^{5}\\ \\text{N/C}$","$8.47\\times10^{4}\\ \\text{N/C}$","$6.78\\times10^{5}\\ \\text{N/C}$","$1.69\\times10^{5}\\ \\text{N/C}$"]'::jsonb, 3, '$E = \sigma/(2\varepsilon_{0}) = 3\times10^{-6}/(2\times8.85\times10^{-12}) = 1.7\times10^{5}\ \text{N/C}$.', 'Electrostatics'),
  ('What is the electric potential $20\ \text{cm}$ from a point charge of $4.0\ \text{nC}$?', '["$180\\ \\text{V}$","$900\\ \\text{V}$","$36\\ \\text{V}$","$18\\ \\text{V}$"]'::jsonb, 0, '$V = kq/r = (8.99\times10^{9})(4\times10^{-9})/0.2 = 180\ \text{V}$.', 'Electrostatics'),
  ('An electron is accelerated from rest through a potential difference of $1000\ \text{V}$. Its kinetic energy is:', '["$1.6\\times10^{-19}\\ \\text{J}$","$1.6\\times10^{-16}\\ \\text{J}$","$1.6\\times10^{-13}\\ \\text{J}$","$1.0\\times10^{3}\\ \\text{J}$"]'::jsonb, 1, '$K = qV = (1.6\times10^{-19})(1000) = 1.6\times10^{-16}\ \text{J} = 1000\ \text{eV}$.', 'Electrostatics'),
  ('A parallel-plate capacitor has plate area $0.010\ \text{m}^{2}$ and separation $2.0\ \text{mm}$. With a dielectric of $\kappa = 4$ filling the gap, the capacitance is:', '["$4.43\\times10^{-11}\\ \\text{F}$","$7.08\\times10^{-10}\\ \\text{F}$","$1.77\\times10^{-10}\\ \\text{F}$","$3.54\\times10^{-10}\\ \\text{F}$"]'::jsonb, 2, '$C = \kappa\varepsilon_{0}A/d = 4(8.85\times10^{-12})(0.01)/(2\times10^{-3}) = 1.77\times10^{-10}\ \text{F}$.', 'Capacitors and Dielectrics'),
  ('A $10\ \mu\text{F}$ capacitor is charged to $100\ \text{V}$. The charge on it is:', '["$1.0\\times10^{-5}\\ \\text{C}$","$1.0\\times10^{-1}\\ \\text{C}$","$5.0\\times10^{-2}\\ \\text{C}$","$1.0\\times10^{-3}\\ \\text{C}$"]'::jsonb, 3, '$Q = CV = (10\times10^{-6})(100) = 1.0\times10^{-3}\ \text{C}$.', 'Capacitors and Dielectrics'),
  ('How much energy is stored in a $10\ \mu\text{F}$ capacitor charged to $100\ \text{V}$?', '["$0.050\\ \\text{J}$","$0.10\\ \\text{J}$","$0.0010\\ \\text{J}$","$0.50\\ \\text{J}$"]'::jsonb, 0, '$U = \tfrac{1}{2}CV^{2} = \tfrac{1}{2}(10\times10^{-6})(10^{4}) = 0.050\ \text{J}$.', 'Capacitors and Dielectrics'),
  ('A capacitor charged to $100\ \text{V}$ discharges through a resistor. After two time constants the voltage is about:', '["$36.8\\ \\text{V}$","$13.5\\ \\text{V}$","$50\\ \\text{V}$","$86.5\\ \\text{V}$"]'::jsonb, 1, '$V = V_{0}e^{-t/\tau}$. At $t = 2\tau$: $V = 100e^{-2} = 13.5\ \text{V}$.', 'Capacitors and Dielectrics'),
  ('A $24\ \Omega$ heater is connected to a $12\ \text{V}$ d.c. supply. The power dissipated is:', '["$288\\ \\text{W}$","$0.5\\ \\text{W}$","$6.0\\ \\text{W}$","$2.0\\ \\text{W}$"]'::jsonb, 2, '$P = V^{2}/R = 144/24 = 6.0\ \text{W}$.', 'Current Electricity and DC Circuits'),
  ('A copper wire of length $10\ \text{m}$ and diameter $1.0\ \text{mm}$ has resistivity $1.7\times10^{-8}\ \Omega\,\text{m}$. Its resistance is about:', '["$0.87\\ \\Omega$","$0.054\\ \\Omega$","$2.2\\ \\Omega$","$0.22\\ \\Omega$"]'::jsonb, 3, '$R = \rho L/A$ with $A = \pi(0.5\times10^{-3})^{2} = 7.85\times10^{-7}\ \text{m}^{2}$. $R = (1.7\times10^{-8})(10)/(7.85\times10^{-7}) = 0.22\ \Omega$.', 'Current Electricity and DC Circuits'),
  ('A uniform wire of resistance $100\ \Omega$ is drawn out uniformly to twice its length. Its new resistance is:', '["$400\\ \\Omega$","$200\\ \\Omega$","$50\\ \\Omega$","$25\\ \\Omega$"]'::jsonb, 0, 'Volume is fixed, so doubling the length halves the area. $R = \rho L/A$ increases by $2\times2 = 4$.', 'Current Electricity and DC Circuits'),
  ('Two batteries, $6\ \text{V}$ and $3\ \text{V}$ (negligible internal resistance), oppose each other in a series loop containing $2\ \Omega$, $4\ \Omega$ and $1\ \Omega$ resistors. The current is:', '["$1.29\\ \\text{A}$","$0.43\\ \\text{A}$","$0.86\\ \\text{A}$","$1.00\\ \\text{A}$"]'::jsonb, 1, 'Net e.m.f. $= 6 - 3 = 3\ \text{V}$; total resistance $= 7\ \Omega$. $I = 3/7 = 0.43\ \text{A}$ (Kirchhoff''s voltage law).', 'Current Electricity and DC Circuits'),
  ('A $12\ \text{V}$ supply is connected across a $3\ \Omega$ and a $6\ \Omega$ resistor in series. The potential difference across the $6\ \Omega$ resistor is:', '["$4.0\\ \\text{V}$","$6.0\\ \\text{V}$","$8.0\\ \\text{V}$","$12\\ \\text{V}$"]'::jsonb, 2, 'Voltage divides in proportion to resistance: $12\times6/9 = 8.0\ \text{V}$.', 'Current Electricity and DC Circuits'),
  ('A cell of e.m.f. $6.0\ \text{V}$ and internal resistance $0.50\ \Omega$ is connected to a $2.5\ \Omega$ resistor. The terminal voltage is:', '["$6.0\\ \\text{V}$","$1.0\\ \\text{V}$","$2.5\\ \\text{V}$","$5.0\\ \\text{V}$"]'::jsonb, 3, '$I = \varepsilon/(R + r) = 6/3 = 2\ \text{A}$. $V = \varepsilon - Ir = 6 - 1 = 5.0\ \text{V}$.', 'Current Electricity and DC Circuits'),
  ('The Bohr radius is $0.0529\ \text{nm}$. The radius of the $n = 3$ orbit of hydrogen is:', '["$0.476\\ \\text{nm}$","$0.159\\ \\text{nm}$","$0.0176\\ \\text{nm}$","$1.43\\ \\text{nm}$"]'::jsonb, 0, '$r_{n} = n^{2}a_{0} = 9(0.0529) = 0.476\ \text{nm}$.', 'Atomic and Nuclear Physics'),
  ('Using $R_{H} = 1.097\times10^{7}\ \text{m}^{-1}$, the wavelength of the first Balmer line ($n = 3\to2$) is:', '["$486\\ \\text{nm}$","$656\\ \\text{nm}$","$122\\ \\text{nm}$","$1875\\ \\text{nm}$"]'::jsonb, 1, '$1/\lambda = R_{H}(1/2^{2} - 1/3^{2}) = (1.097\times10^{7})(5/36)$, so $\lambda = 6.56\times10^{-7}\ \text{m} = 656\ \text{nm}$.', 'Atomic and Nuclear Physics'),
  ('The energy of a photon emitted when a hydrogen electron falls from $n = 2$ to $n = 1$ is:', '["$13.6\\ \\text{eV}$","$3.4\\ \\text{eV}$","$10.2\\ \\text{eV}$","$1.9\\ \\text{eV}$"]'::jsonb, 2, '$E_{n} = -13.6/n^{2}$. $E_{2} - E_{1} = -3.4 - (-13.6) = 10.2\ \text{eV}$.', 'Atomic and Nuclear Physics'),
  ('A radioactive sample has a half-life of $5.0$ days. If $800\ \text{mg}$ is present initially, the mass remaining after $15$ days is:', '["$200\\ \\text{mg}$","$266\\ \\text{mg}$","$400\\ \\text{mg}$","$100\\ \\text{mg}$"]'::jsonb, 3, '$15$ days is $3$ half-lives: $800\times(1/2)^{3} = 100\ \text{mg}$.', 'Atomic and Nuclear Physics'),
  ('A nuclide has a half-life of $5.0$ days. Its decay constant is about:', '["$1.6\\times10^{-6}\\ \\text{s}^{-1}$","$1.4\\times10^{-1}\\ \\text{s}^{-1}$","$2.3\\times10^{-6}\\ \\text{s}^{-1}$","$1.6\\times10^{-3}\\ \\text{s}^{-1}$"]'::jsonb, 0, '$\lambda = \ln2/T_{1/2} = 0.693/(5\times86\,400) = 1.6\times10^{-6}\ \text{s}^{-1}$.', 'Atomic and Nuclear Physics'),
  ('In a nuclear reaction the total mass decreases by $0.0020\ \text{u}$. The energy released is about:', '["$18.6\\ \\text{MeV}$","$1.86\\ \\text{MeV}$","$0.186\\ \\text{MeV}$","$931\\ \\text{MeV}$"]'::jsonb, 1, '$E = \Delta m\times931.49 = 0.002\times931.49 = 1.86\ \text{MeV}$.', 'Atomic and Nuclear Physics'),
  ('A beta-minus decay changes the nucleus $^{A}_{Z}\text{X}$ into:', '["$^{A}_{Z-1}\\text{Y}$","$^{A-4}_{Z-2}\\text{Y}$","$^{A}_{Z+1}\\text{Y}$","$^{A-1}_{Z}\\text{Y}$"]'::jsonb, 2, 'A neutron turns into a proton, so $A$ is unchanged and $Z$ rises by one.', 'Atomic and Nuclear Physics'),
  ('Gamma rays differ from X-rays mainly in that gamma rays:', '["are charged particles","cannot ionise matter","travel more slowly in vacuum","come from the nucleus"]'::jsonb, 3, 'Both are electromagnetic radiation travelling at $c$. Gamma rays originate in nuclear transitions, X-rays in electron transitions or deceleration.', 'Atomic and Nuclear Physics')
),
tgt as (
  select subject_id, subject_name, faculty, department, level, semester, units
    from public.cbt_questions
   where (subject_name ilike 'PHY 102%' or subject_id = 'phy-124-electricity-magnetism-atomic')
     and subject_id not like '%coming-soon'
   limit 1
)
insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general, semester, units)
select coalesce(t.subject_id, 'phy-124-electricity-magnetism-atomic'),
       coalesce(t.subject_name, 'PHY 102: Electricity, Magnetism and Atomic Physics'),
       'University of Nigeria, Nsukka',
       coalesce(t.faculty, 'Faculty of Physical Sciences, Faculty of Engineering'),
       coalesce(t.department, 'Physics and Astronomy'),
       coalesce(t.level, '100 Level'),
       s.question, s.options, s.correct_index, s.explanation, s.topic, false,
       coalesce(t.semester, 'second'),
       coalesce(t.units, 3)
  from src s
  left join tgt t on true
 where not exists (
   select 1 from public.cbt_questions c
    where c.subject_id = coalesce(t.subject_id, 'phy-124-electricity-magnetism-atomic') and c.question = s.question);

select subject_id, subject_name, count(*) as questions
  from public.cbt_questions
 where subject_id = 'phy-124-electricity-magnetism-atomic'
 group by 1, 2;
